mapper.select:
select ta.test_answer_id, t.test_name, u.nick_name, ta.user_test_score, ta.sum_score, ta.duration, ta.submit_time, (select count(*) from ms_question_answer qa where test_answer_id=ta.test_answer_id and qa.`status`=1) as right_count, (select count(*) from ms_test_question tq where tq.test_id=ta.test_id and tq.del_flag='0') as question_count from ms_test_answer ta left join ms_test t on ta.test_id=t.test_id left join sys_user u on ta.user_id=u.user_id where ta.del_flag='0'
and t.subject_id=#{subjectId}
and ta.`status`=#{status}
and ta.user_id in
#{userId}
